contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public payable {
        require(true);
        // Fresh pool: this contract holds zero shares.
        uint256 balSender = c.balanceOf(address(this));
        uint256 balTo = c.balanceOf(to);

        bool reverted;
        // top-level state-changing call
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // General rule: transfer reverts iff amount exceeds the sender's balance;
        // when it succeeds it moves exactly `amount` of shares from sender to `to`.
        assert(
            (reverted && amount > balSender)
            ||
            (!reverted && amount <= balSender
                && balToAfter == balTo + amount
                && balSenderAfter + amount == balSender)
        );
    }

    receive() external payable {}
}

