contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address spender,
        address to,
        uint256 approveAmt,
        uint256 amount
    ) public {
        require(spender != address(0));
        require(to != address(0));

        // Approve an arbitrary allowance for an arbitrary spender.
        c.approve(spender, approveAmt);

        // Snapshot balances/allowance before the deciding call.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 allowBefore = c.allowance(address(this), spender);

        // transferFrom from our own balance (fresh pool: balance is 0).
        bool reverted;
        try c.transferFrom(address(this), to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: transferFrom must revert exactly when the amount
        // exceeds the sender's share balance OR the granted allowance.
        assert(reverted == (amount > balBefore || amount > allowBefore));
    }

    receive() external payable {}
}

